import operator
import sys

DIV0 = "#DIV/0!"
CYCLE = "#CYCLE!"
COMPARE = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


def _tokenize(text):
    tokens = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < len(text) and text[j].isdigit():
                j += 1
            tokens.append(("num", int(text[i:j])))
            i = j
        elif "A" <= ch <= "Z":
            j = i
            while j < len(text) and "A" <= text[j] <= "Z":
                j += 1
            k = j
            while k < len(text) and text[k].isdigit():
                k += 1
            if j - i == 1 and k > j:
                tokens.append(("cell", text[i:k]))
                i = k
            else:
                tokens.append(("name", text[i:j]))
                i = j
        elif text[i:i + 2] in ("<>", "<=", ">="):
            tokens.append(("op", text[i:i + 2]))
            i += 2
        else:
            tokens.append(("op", ch))
            i += 1
    return tokens


def _parse(text):
    toks = _tokenize(text)
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        pos += 1
        return toks[pos - 1]

    def parse_expr():
        node = parse_term()
        while peek() in (("op", "+"), ("op", "-")):
            op = take()[1]
            node = ("bin", op, node, parse_term())
        return node

    def parse_term():
        node = parse_unary()
        while peek() in (("op", "*"), ("op", "/")):
            op = take()[1]
            node = ("bin", op, node, parse_unary())
        return node

    def parse_unary():
        if peek() == ("op", "-"):
            take()
            return ("neg", parse_unary())
        return parse_atom()

    def parse_atom():
        tok = take()
        if tok[0] == "num":
            return ("num", tok[1])
        if tok[0] == "cell":
            return ("ref", tok[1])
        if tok == ("op", "("):
            node = parse_expr()
            take()
            return node
        take()  # "("
        if tok[1] == "IF":
            left = parse_expr()
            op = take()[1]
            right = parse_expr()
            take()  # ","
            then = parse_expr()
            take()  # ","
            other = parse_expr()
            take()  # ")"
            return ("if", op, left, right, then, other)
        args = []
        while True:
            nxt = peek()
            after = toks[pos + 1] if pos + 1 < len(toks) else None
            if nxt[0] == "cell" and after == ("op", ":"):
                first = take()[1]
                take()  # ":"
                second = take()[1]
                args.append(("range", first, second))
            else:
                args.append(parse_expr())
            if peek() == ("op", ","):
                take()
            else:
                break
        take()  # ")"
        return ("call", tok[1], args)

    return parse_expr()


def _range_names(first, second):
    c1, r1 = ord(first[0]) - 65, int(first[1:])
    c2, r2 = ord(second[0]) - 65, int(second[1:])
    for row in range(min(r1, r2), max(r1, r2) + 1):
        for col in range(min(c1, c2), max(c1, c2) + 1):
            yield chr(65 + col) + str(row)


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
    values = {}
    busy = set()

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in busy:
            return CYCLE
        busy.add(name)
        text = cells[name].strip()
        if text.startswith("="):
            result = evaluate(_parse(text[1:]))
        else:
            result = int(text)
        busy.discard(name)
        values[name] = result
        return result

    def evaluate(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return cell_value(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value
        if kind == "bin":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return DIV0
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            _, op, left_node, right_node, then_node, else_node = node
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right
            return evaluate(then_node if COMPARE[op](left, right) else else_node)
        fname, args = node[1], node[2]
        collected = []
        for arg in args:
            if arg[0] == "range":
                for target in _range_names(arg[1], arg[2]):
                    if target not in cells:
                        continue
                    value = cell_value(target)
                    if isinstance(value, str):
                        return value
                    collected.append(value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                collected.append(value)
        if fname == "SUM":
            return sum(collected)
        if not collected:
            return 0
        return min(collected) if fname == "MIN" else max(collected)

    return {name: cell_value(name) for name in cells}
